-- ===== 0002_search.sql =====
-- =====================================================================
-- Migration 0002: advanced business search (typo/tashkeel tolerant)
-- =====================================================================

create or replace function public.search_businesses(
  p_q          text    default null,
  p_category   text    default null,     -- category slug (includes its children)
  p_district   int     default null,
  p_min_rating numeric default 0,
  p_open_now   boolean default false,
  p_verified   boolean default false,
  p_lat        float8  default null,
  p_lng        float8  default null,
  p_sort       text    default 'relevance',  -- relevance | nearest | rating | newest
  p_limit      int     default 24,
  p_offset     int     default 0
)
returns table (
  id uuid, slug text, name text, description text, phone text, whatsapp text, address text,
  is_verified boolean, is_featured boolean, rating_avg numeric, rating_count int,
  lat float8, lng float8, district_id int, category_id int, logo_url text,
  is_open boolean, distance_km float8, total_count bigint
)
language sql stable
set search_path = public
set pg_trgm.word_similarity_threshold = '0.4'
as $$
  with q as (select nullif(trim(public.ar_normalize(p_q)), '') as qn),
  cats as (
    select c.id from public.categories c
    where p_category is not null
      and (c.slug = p_category or c.parent_id = (select x.id from public.categories x where x.slug = p_category))
  ),
  base as (
    select b.*,
      case when p_lat is not null and p_lng is not null and b.lat is not null
           then public.distance_km(p_lat, p_lng, b.lat, b.lng) end as dist,
      public.is_open_now(b.id) as open_now,
      (b.is_featured and (b.featured_until is null or b.featured_until > now())) as feat,
      case when q.qn is null then 0
           else greatest(word_similarity(q.qn, b.search_norm),
                         case when b.search_norm like '%' || q.qn || '%' then 1 else 0 end) end as sc
    from public.businesses b, q
    where b.status = 'active'
      and (p_category is null or b.category_id in (select cid.id from cats cid))
      and (p_district is null or b.district_id = p_district)
      and b.rating_avg >= coalesce(p_min_rating, 0)
      and (not p_verified or b.is_verified)
      and (q.qn is null or b.search_norm like '%' || q.qn || '%' or q.qn <% b.search_norm)
  )
  select base.id, base.slug, base.name, base.description, base.phone, base.whatsapp, base.address,
         base.is_verified, base.feat, base.rating_avg, base.rating_count,
         base.lat, base.lng, base.district_id, base.category_id, base.logo_url,
         base.open_now, base.dist, count(*) over()
  from base
  where (not p_open_now or base.open_now)
  order by
    case when p_sort = 'nearest'   then base.dist end asc nulls last,
    case when p_sort = 'rating'    then base.rating_avg end desc,
    case when p_sort = 'newest'    then base.created_at end desc,
    case when p_sort = 'relevance' then base.feat::int end desc,
    base.sc desc, base.rating_avg desc, base.name
  limit least(greatest(p_limit, 1), 100) offset greatest(p_offset, 0);
$$;
grant execute on function public.search_businesses(text,text,int,numeric,boolean,boolean,float8,float8,text,int,int) to anon, authenticated;


-- ===== 0003_social.sql =====
-- =====================================================================
-- Migration 0003: social feed, stories rings, automatic notifications
-- =====================================================================

alter table public.notifications drop constraint if exists notifications_type_check;
alter table public.notifications add constraint notifications_type_check
  check (type in ('follow','comment','like','review','review_reply','offer','post','message','verification','system'));

-- ---------------------------------------------------------------------
-- Feed: one round trip with author, business, media and liked-by-me.
--   p_mode 'following' = only businesses the caller follows.
-- ---------------------------------------------------------------------
create or replace function public.get_feed(
  p_mode     text        default 'all',
  p_before   timestamptz default null,
  p_limit    int         default 10,
  p_business uuid        default null,
  p_author   uuid        default null,
  p_post     uuid        default null
)
returns table (
  id uuid, body text, is_offer boolean, offer_ends_at timestamptz,
  likes_count int, comments_count int, created_at timestamptz,
  author jsonb, business jsonb, media jsonb, liked boolean
)
language sql stable set search_path = public as $$
  select p.id, p.body, p.is_offer, p.offer_ends_at, p.likes_count, p.comments_count, p.created_at,
         jsonb_build_object('id', a.id, 'full_name', a.full_name, 'username', a.username, 'avatar_url', a.avatar_url),
         case when b.id is null then null
              else jsonb_build_object('id', b.id, 'slug', b.slug, 'name', b.name, 'logo_url', b.logo_url, 'is_verified', b.is_verified) end,
         coalesce((select jsonb_agg(jsonb_build_object('url', m.url, 'width', m.width, 'height', m.height) order by m.sort_order)
                   from public.post_media m where m.post_id = p.id), '[]'::jsonb),
         exists (select 1 from public.likes l where l.post_id = p.id and l.user_id = auth.uid())
  from public.posts p
  join public.profiles a on a.id = p.author_id
  left join public.businesses b on b.id = p.business_id
  where not p.is_hidden
    and (p.business_id is null or b.status = 'active')
    and (p_before   is null or p.created_at < p_before)
    and (p_business is null or p.business_id = p_business)
    and (p_author   is null or p.author_id = p_author)
    and (p_post     is null or p.id = p_post)
    and (p_mode <> 'following' or p.business_id in (select f.business_id from public.follows f where f.user_id = auth.uid()))
    and not exists (select 1 from public.user_blocks ub where ub.blocker_id = auth.uid() and ub.blocked_id = p.author_id)
  order by p.created_at desc
  limit least(greatest(p_limit, 1), 50);
$$;
grant execute on function public.get_feed(text, timestamptz, int, uuid, uuid, uuid) to anon, authenticated;

-- ---------------------------------------------------------------------
-- Stories: businesses with at least one live story (followed first).
-- ---------------------------------------------------------------------
create or replace function public.get_story_rings()
returns table (business_id uuid, slug text, name text, logo_url text, is_verified boolean,
               followed boolean, stories jsonb, latest timestamptz)
language sql stable set search_path = public as $$
  select b.id, b.slug, b.name, b.logo_url, b.is_verified,
         exists (select 1 from public.follows f where f.business_id = b.id and f.user_id = auth.uid()) as followed,
         jsonb_agg(jsonb_build_object('id', s.id, 'media_url', s.media_url, 'caption', s.caption, 'created_at', s.created_at)
                   order by s.created_at) as stories,
         max(s.created_at) as latest
  from public.stories s
  join public.businesses b on b.id = s.business_id and b.status = 'active'
  where s.expires_at > now()
  group by b.id
  order by followed desc, latest desc
  limit 30;
$$;
grant execute on function public.get_story_rings() to anon, authenticated;

create or replace function public.unread_notifications()
returns int language sql stable set search_path = public as $$
  select count(*)::int from public.notifications where user_id = auth.uid() and read_at is null;
$$;
grant execute on function public.unread_notifications() to authenticated;

-- ---------------------------------------------------------------------
-- Notification producers (SECURITY DEFINER; users can never forge them)
-- ---------------------------------------------------------------------
create or replace function public.notify_follow()
returns trigger language plpgsql security definer set search_path = public as $$
declare owner uuid;
begin
  select owner_id into owner from public.businesses where id = new.business_id;
  if owner is not null and owner <> new.user_id then
    insert into public.notifications (user_id, type, actor_id, business_id)
    values (owner, 'follow', new.user_id, new.business_id);
  end if;
  return null;
end $$;
create trigger trg_notify_follow after insert on public.follows
  for each row execute function public.notify_follow();

create or replace function public.notify_like()
returns trigger language plpgsql security definer set search_path = public as $$
declare author uuid;
begin
  select author_id into author from public.posts where id = new.post_id;
  if author is not null and author <> new.user_id
     and not exists (select 1 from public.notifications n
                     where n.user_id = author and n.type = 'like' and n.actor_id = new.user_id and n.post_id = new.post_id) then
    insert into public.notifications (user_id, type, actor_id, post_id) values (author, 'like', new.user_id, new.post_id);
  end if;
  return null;
end $$;
create trigger trg_notify_like after insert on public.likes
  for each row execute function public.notify_like();

create or replace function public.notify_comment()
returns trigger language plpgsql security definer set search_path = public as $$
declare author uuid;
begin
  select author_id into author from public.posts where id = new.post_id;
  if author is not null and author <> new.author_id then
    insert into public.notifications (user_id, type, actor_id, post_id, data)
    values (author, 'comment', new.author_id, new.post_id, jsonb_build_object('excerpt', left(new.body, 80)));
  end if;
  return null;
end $$;
create trigger trg_notify_comment after insert on public.comments
  for each row execute function public.notify_comment();

create or replace function public.notify_followers_of_post()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.business_id is not null then
    insert into public.notifications (user_id, type, actor_id, business_id, post_id, data)
    select f.user_id, case when new.is_offer then 'offer' else 'post' end, new.author_id, new.business_id, new.id,
           jsonb_build_object('excerpt', left(new.body, 80))
    from public.follows f
    where f.business_id = new.business_id and f.user_id <> new.author_id;
  end if;
  return null;
end $$;
create trigger trg_notify_post after insert on public.posts
  for each row execute function public.notify_followers_of_post();

-- ---------------------------------------------------------------------
-- Fix: privilege guards must only restrict *direct* client writes.
-- Counter triggers / RPCs run as SECURITY DEFINER (current_user = owner), so
-- they must be allowed to change counters. The guards are therefore SECURITY
-- INVOKER and key off current_user instead of auth.uid().
-- ---------------------------------------------------------------------
create or replace function public.guard_profile_privileged()
returns trigger language plpgsql set search_path = public as $$
begin
  if current_user in ('anon', 'authenticated') and not public.is_admin() then
    new.role := old.role;
    new.is_banned := old.is_banned;
  end if;
  return new;
end $$;

create or replace function public.guard_business_privileged()
returns trigger language plpgsql set search_path = public as $$
begin
  if current_user in ('anon', 'authenticated') and not public.is_staff() then
    if tg_op = 'INSERT' then
      new.status := 'pending';
      new.is_verified := false;
      new.is_featured := false;
      new.featured_until := null;
      new.owner_id := auth.uid();
    else
      new.status := old.status;
      new.is_verified := old.is_verified;
      new.is_featured := old.is_featured;
      new.featured_until := old.featured_until;
      new.owner_id := old.owner_id;
      new.rating_avg := old.rating_avg;
      new.rating_count := old.rating_count;
      new.followers_count := old.followers_count;
      new.views_count := old.views_count;
      new.call_clicks := old.call_clicks;
    end if;
  end if;
  return new;
end $$;

create or replace function public.guard_listing_privileged()
returns trigger language plpgsql set search_path = public as $$
begin
  if current_user in ('anon', 'authenticated') and not public.is_staff() then
    if tg_op = 'INSERT' then
      new.is_featured := false; new.featured_until := null;
    else
      new.is_featured := old.is_featured; new.featured_until := old.featured_until;
      new.views_count := old.views_count;
    end if;
  end if;
  return new;
end $$;

-- Rate limiting is also skipped for definer/service contexts (seed, jobs).
create or replace function public.enforce_rate_limit()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  col   text := tg_argv[0];
  maxn  int  := tg_argv[1]::int;
  win   interval := tg_argv[2]::interval;
  uid   uuid;
  n     int;
begin
  if auth.uid() is null then return new; end if;
  if public.is_banned() then raise exception 'account_banned' using errcode = 'P0001'; end if;
  uid := (to_jsonb(new) ->> col)::uuid;
  execute format('select count(*) from %I.%I where %I = $1 and created_at > now() - $2',
                 tg_table_schema, tg_table_name, col) into n using uid, win;
  if n >= maxn then raise exception 'rate_limited' using errcode = 'P0001'; end if;
  return new;
end $$;


-- ===== 0004_reviews_listings_live.sql =====
-- =====================================================================
-- Migration 0004: reviews hardening, listings search, live service status
-- =====================================================================

-- ---------------------------------------------------------------------
-- Reviews: a reviewer may only edit rating/body of their own review.
-- Owner reply / hidden flag / ownership fields are protected.
-- ---------------------------------------------------------------------
create or replace function public.guard_review_privileged()
returns trigger language plpgsql set search_path = public as $$
begin
  if current_user in ('anon', 'authenticated') and not public.is_staff() then
    if tg_op = 'INSERT' then
      new.owner_reply := null; new.replied_at := null; new.is_hidden := false; new.user_id := auth.uid();
    else
      new.owner_reply := old.owner_reply; new.replied_at := old.replied_at; new.is_hidden := old.is_hidden;
      new.business_id := old.business_id; new.user_id := old.user_id;
    end if;
  end if;
  return new;
end $$;
create trigger trg_reviews_guard before insert or update on public.reviews
  for each row execute function public.guard_review_privileged();

-- Notify the owner of new reviews.
create or replace function public.notify_review()
returns trigger language plpgsql security definer set search_path = public as $$
declare owner uuid;
begin
  select owner_id into owner from public.businesses where id = new.business_id;
  if owner is not null and owner <> new.user_id then
    insert into public.notifications (user_id, type, actor_id, business_id, data)
    values (owner, 'review', new.user_id, new.business_id,
            jsonb_build_object('rating', new.rating, 'excerpt', left(coalesce(new.body, ''), 80)));
  end if;
  return null;
end $$;
create trigger trg_notify_review after insert on public.reviews
  for each row execute function public.notify_review();

-- Owner reply now also notifies the reviewer.
create or replace function public.reply_to_review(p_review uuid, p_reply text)
returns void language plpgsql security definer set search_path = public as $$
declare r public.reviews;
begin
  select * into r from public.reviews where id = p_review;
  if not found or not public.owns_business(r.business_id) or coalesce(trim(p_reply), '') = '' then
    raise exception 'not_allowed';
  end if;
  update public.reviews set owner_reply = left(trim(p_reply), 1000), replied_at = now() where id = p_review;
  insert into public.notifications (user_id, type, actor_id, business_id, data)
  values (r.user_id, 'review_reply', auth.uid(), r.business_id, jsonb_build_object('excerpt', left(trim(p_reply), 80)));
end $$;
grant execute on function public.reply_to_review(uuid, text) to authenticated;

-- ---------------------------------------------------------------------
-- Listings search (real estate / vehicles / jobs)
-- ---------------------------------------------------------------------
create or replace function public.search_listings(
  p_kind       listing_kind,
  p_q          text    default null,
  p_deal       text    default null,     -- details.deal   (sale | rent | wanted)
  p_type       text    default null,     -- details.type
  p_district   int     default null,
  p_currency   text    default null,
  p_min_price  numeric default null,
  p_max_price  numeric default null,
  p_min_area   numeric default null,
  p_min_rooms  int     default null,
  p_min_year   int     default null,
  p_employment text    default null,
  p_sort       text    default 'newest', -- newest | price_asc | price_desc
  p_limit      int     default 18,
  p_offset     int     default 0
)
returns table (
  id uuid, kind listing_kind, title text, price numeric, currency text, details jsonb,
  district_id int, is_featured boolean, created_at timestamptz, image text, total_count bigint
)
language sql stable set search_path = public as $$
  with q as (select nullif(trim(public.ar_normalize(p_q)), '') as qn),
  base as (
    select l.*, (l.is_featured and (l.featured_until is null or l.featured_until > now())) as feat
    from public.listings l, q
    where l.kind = p_kind and l.status = 'active'
      and (q.qn is null or l.search_norm like '%' || q.qn || '%')
      and (p_deal is null or l.details->>'deal' = p_deal)
      and (p_type is null or l.details->>'type' = p_type)
      and (p_district is null or l.district_id = p_district)
      and (p_currency is null or l.currency = p_currency)
      and (p_min_price is null or l.price >= p_min_price)
      and (p_max_price is null or l.price <= p_max_price)
      and (p_min_area  is null or (l.details->>'area_m2')::numeric >= p_min_area)
      and (p_min_rooms is null or (l.details->>'rooms')::int >= p_min_rooms)
      and (p_min_year  is null or (l.details->>'year')::int >= p_min_year)
      and (p_employment is null or l.details->>'employment' = p_employment)
  )
  select b.id, b.kind, b.title, b.price, b.currency, b.details, b.district_id, b.feat, b.created_at,
         (select i.url from public.listing_images i where i.listing_id = b.id order by i.sort_order limit 1),
         count(*) over()
  from base b
  order by b.feat desc,
           case when p_sort = 'price_asc'  then b.price end asc nulls last,
           case when p_sort = 'price_desc' then b.price end desc nulls last,
           b.created_at desc
  limit least(greatest(p_limit, 1), 60) offset greatest(p_offset, 0);
$$;
grant execute on function public.search_listings(listing_kind,text,text,text,int,text,numeric,numeric,numeric,int,int,text,text,int,int) to anon, authenticated;

-- Views counter for listings (RPC, since direct UPDATE is guarded).
create or replace function public.track_listing(p_id uuid)
returns void language sql security definer set search_path = public as $$
  update public.listings set views_count = views_count + 1 where id = p_id and status = 'active';
$$;
grant execute on function public.track_listing(uuid) to anon, authenticated;

-- ---------------------------------------------------------------------
-- Live service status (fuel / water): latest crowd report in the last 6h.
-- ---------------------------------------------------------------------
create or replace function public.get_service_status(p_category text)
returns table (
  id uuid, slug text, name text, address text, phone text, district_id int, is_open boolean,
  status avail_status, queue_level smallint, note text, reported_at timestamptz, recent_reports bigint
)
language sql stable set search_path = public as $$
  select b.id, b.slug, b.name, b.address, b.phone, b.district_id, public.is_open_now(b.id),
         r.status, r.queue_level, r.note, r.created_at,
         (select count(*) from public.service_status_reports x where x.business_id = b.id and x.created_at > now() - interval '3 hours')
  from public.businesses b
  left join lateral (
    select s.* from public.service_status_reports s
    where s.business_id = b.id and s.created_at > now() - interval '6 hours'
    order by s.created_at desc limit 1
  ) r on true
  where b.status = 'active'
    and b.category_id in (select c.id from public.categories c where c.slug = p_category)
  order by case r.status when 'available' then 0 when 'queue' then 1 when null then 2 else 3 end, b.name;
$$;
grant execute on function public.get_service_status(text) to anon, authenticated;


