-- ---------------------------------------------------------------------
-- Offers (auto-expire by ends_at) and events
-- ---------------------------------------------------------------------
create table public.offers (
  id          uuid primary key default gen_random_uuid(),
  business_id uuid not null references public.businesses(id) on delete cascade,
  city_id     int not null references public.cities(id),
  title       text not null check (char_length(title) between 3 and 140),
  details     text check (char_length(details) <= 1000),
  image_url   text,
  starts_at   timestamptz not null default now(),
  ends_at     timestamptz not null,
  status      text not null default 'published' check (status in ('published', 'hidden')),
  created_at  timestamptz not null default now(),
  check (ends_at > starts_at)
);
create index offers_live_idx on public.offers(city_id, ends_at) where status = 'published';
create index offers_biz_idx on public.offers(business_id);

create or replace function public.offers_set_city()
returns trigger language plpgsql as $$
begin
  select city_id into new.city_id from public.businesses where id = new.business_id;
  return new;
end $$;
create trigger trg_offers_city before insert on public.offers for each row execute function public.offers_set_city();

create table public.events (
  id                uuid primary key default gen_random_uuid(),
  city_id           int not null default 1 references public.cities(id),
  title             text not null check (char_length(title) between 3 and 140),
  details           text check (char_length(details) <= 2000),
  category          text check (category in ('music','family','sports','culture','food','education','charity','other')),
  starts_at         timestamptz not null,
  ends_at           timestamptz,
  venue_business_id uuid references public.businesses(id) on delete set null,
  venue_name        text,
  lat               float8,
  lng               float8,
  image_url         text,
  status            text not null default 'pending' check (status in ('pending', 'published', 'hidden')),
  created_by        uuid references public.profiles(id) on delete set null,
  created_at        timestamptz not null default now()
);
create index events_live_idx on public.events(city_id, starts_at) where status = 'published';

-- Only staff publish events; everyone else's go to the review queue.
create or replace function public.guard_event()
returns trigger language plpgsql set search_path = public as $$
begin
  if current_user in ('anon', 'authenticated') and not public.is_staff() then
    if tg_op = 'INSERT' then new.status := 'pending'; new.created_by := auth.uid();
    else new.status := old.status; new.created_by := old.created_by; end if;
  end if;
  return new;
end $$;
create trigger trg_events_guard before insert or update on public.events for each row execute function public.guard_event();

alter table public.offers enable row level security;
alter table public.events enable row level security;
create policy offers_read on public.offers for select
  using ((status = 'published' and starts_at <= now() and ends_at > now()) or public.owns_business(business_id) or public.is_staff());
create policy offers_write on public.offers for all
  using (public.owns_business(business_id) or public.is_staff()) with check (public.owns_business(business_id) or public.is_staff());
create policy events_read on public.events for select
  using (status = 'published' or created_by = auth.uid() or public.is_staff());
create policy events_insert on public.events for insert with check (auth.uid() is not null and not public.is_banned());
create policy events_update on public.events for update using (public.is_staff() or created_by = auth.uid()) with check (public.is_staff() or created_by = auth.uid());
create policy events_delete on public.events for delete using (public.is_staff() or created_by = auth.uid());

-- ---------------------------------------------------------------------
-- Community submissions (new place / edit), ownership claims
-- ---------------------------------------------------------------------
create table public.submissions (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null references public.profiles(id) on delete cascade,
  city_id     int not null default 1 references public.cities(id),
  type        text not null check (type in ('new_place', 'edit')),
  business_id uuid references public.businesses(id) on delete cascade,
  payload     jsonb not null,
  status      text not null default 'pending' check (status in ('pending', 'approved', 'rejected')),
  reviewed_by uuid references public.profiles(id) on delete set null,
  review_note text,
  created_at  timestamptz not null default now(),
  reviewed_at timestamptz
);
create index submissions_status_idx on public.submissions(status, created_at);

create table public.claims (
  id          uuid primary key default gen_random_uuid(),
  business_id uuid not null references public.businesses(id) on delete cascade,
  user_id     uuid not null references public.profiles(id) on delete cascade,
  phone       text not null,
  proof_path  text,                         -- private storage path
  status      text not null default 'pending' check (status in ('pending', 'approved', 'rejected')),
  reviewed_by uuid references public.profiles(id) on delete set null,
  created_at  timestamptz not null default now(),
  unique (business_id, user_id)
);
alter table public.submissions enable row level security;
alter table public.claims      enable row level security;
create policy sub2_insert on public.submissions for insert with check (user_id = auth.uid() and status = 'pending' and not public.is_banned());
create policy sub2_read   on public.submissions for select using (user_id = auth.uid() or public.is_staff());
create policy sub2_update on public.submissions for update using (public.is_staff()) with check (public.is_staff());
create policy cl_insert on public.claims for insert with check (user_id = auth.uid() and status = 'pending' and not public.is_banned());
create policy cl_read   on public.claims for select using (user_id = auth.uid() or public.is_staff());
create policy cl_update on public.claims for update using (public.is_staff()) with check (public.is_staff());

create trigger rl_submissions before insert on public.submissions for each row execute function public.enforce_rate_limit('user_id', '10', '1 day');
create trigger rl_events      before insert on public.events      for each row execute function public.enforce_rate_limit('created_by', '5', '1 day');

-- Approving a claim hands the business to the claimant (atomic).
create or replace function public.review_claim(p_claim uuid, p_approve boolean)
returns void language plpgsql security definer set search_path = public as $$
declare c public.claims;
begin
  if not public.is_staff() then raise exception 'not_allowed'; end if;
  update public.claims set status = case when p_approve then 'approved' else 'rejected' end, reviewed_by = auth.uid()
   where id = p_claim returning * into c;
  if p_approve and c.id is not null then
    update public.businesses set owner_id = c.user_id where id = c.business_id;
    update public.profiles set role = 'owner' where id = c.user_id and role = 'user';
  end if;
  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (auth.uid(), 'review_claim', 'claim', p_claim::text, jsonb_build_object('approved', p_approve));
end $$;
grant execute on function public.review_claim(uuid, boolean) to authenticated;

-- ---------------------------------------------------------------------
-- Analytics events (insert through RPC only; staff read)
-- ---------------------------------------------------------------------
create table public.analytics_events (
  id          bigserial primary key,
  event       text not null check (event in ('view','call','whatsapp','directions','save','share','search')),
  target_type text check (target_type in ('business','offer','event','listing')),
  target_id   uuid,
  city_id     int,
  user_id     uuid,
  created_at  timestamptz not null default now()
);
create index analytics_target_idx on public.analytics_events(target_type, target_id, created_at);
create index analytics_time_idx on public.analytics_events(created_at);
alter table public.analytics_events enable row level security;
create policy analytics_read on public.analytics_events for select
  using (public.is_staff() or (target_type = 'business' and public.owns_business(target_id)));

create or replace function public.track_event(p_event text, p_type text default null, p_id uuid default null)
returns void language plpgsql security definer set search_path = public as $$
declare cid int;
begin
  if p_event not in ('view','call','whatsapp','directions','save','share','search') then return; end if;
  if p_type = 'business' and p_id is not null then select city_id into cid from public.businesses where id = p_id; end if;
  insert into public.analytics_events (event, target_type, target_id, city_id, user_id) values (p_event, p_type, p_id, cid, auth.uid());
  if p_type = 'business' and p_event = 'view' then update public.businesses set views_count = views_count + 1 where id = p_id;
  elsif p_type = 'business' and p_event in ('call', 'whatsapp') then update public.businesses set call_clicks = call_clicks + 1 where id = p_id; end if;
end $$;
grant execute on function public.track_event(text, text, uuid) to anon, authenticated;

-- ---------------------------------------------------------------------
-- City-aware search: add p_city (trailing, default null = all cities)
-- ---------------------------------------------------------------------
drop function if exists public.search_businesses(text,text,int,numeric,boolean,boolean,float8,float8,text,int,int);
create or replace function public.search_businesses(
  p_q text default null, p_category text default null, p_district int default null, p_min_rating numeric default 0,
  p_open_now boolean default false, p_verified boolean default false, p_lat float8 default null, p_lng float8 default null,
  p_sort text default 'relevance', p_limit int default 24, p_offset int default 0, p_city int default null
)
returns table (
  id uuid, slug text, name text, description text, phone text, whatsapp text, address text,
  is_verified boolean, is_featured boolean, rating_avg numeric, rating_count int,
  lat float8, lng float8, district_id int, category_id int, logo_url text,
  is_open boolean, distance_km float8, total_count bigint, last_verified_at timestamptz
)
language sql stable set search_path = public set pg_trgm.word_similarity_threshold = '0.4'
as $$
  with q as (select nullif(trim(public.ar_normalize(p_q)), '') as qn),
  cats as (
    select c.id from public.categories c
    where p_category is not null
      and (c.slug = p_category or c.parent_id = (select x.id from public.categories x where x.slug = p_category))
  ),
  base as (
    select b.*,
      case when p_lat is not null and p_lng is not null and b.lat is not null then public.distance_km(p_lat, p_lng, b.lat, b.lng) end as dist,
      public.is_open_now(b.id) as open_now,
      (b.is_featured and (b.featured_until is null or b.featured_until > now())) as feat,
      case when q.qn is null then 0
           else greatest(word_similarity(q.qn, b.search_norm), case when b.search_norm like '%' || q.qn || '%' then 1 else 0 end) end as sc
    from public.businesses b, q
    where b.status = 'active'
      and (p_city is null or b.city_id = p_city)
      and (p_category is null or b.category_id in (select cid.id from cats cid))
      and (p_district is null or b.district_id = p_district)
      and b.rating_avg >= coalesce(p_min_rating, 0)
      and (not p_verified or b.is_verified)
      and (q.qn is null or b.search_norm like '%' || q.qn || '%' or q.qn <% b.search_norm)
  )
  select base.id, base.slug, base.name, base.description, base.phone, base.whatsapp, base.address,
         base.is_verified, base.feat, base.rating_avg, base.rating_count, base.lat, base.lng, base.district_id, base.category_id,
         base.logo_url, base.open_now, base.dist, count(*) over(), base.last_verified_at
  from base
  where (not p_open_now or coalesce(base.open_now, false))
  order by
    case when p_sort = 'nearest'   then base.dist end asc nulls last,
    case when p_sort = 'rating'    then base.rating_avg end desc,
    case when p_sort = 'newest'    then base.created_at end desc,
    case when p_sort = 'relevance' then base.feat::int end desc,
    base.sc desc, base.rating_avg desc, base.name
  limit least(greatest(p_limit, 1), 100) offset greatest(p_offset, 0);
$$;
grant execute on function public.search_businesses(text,text,int,numeric,boolean,boolean,float8,float8,text,int,int,int) to anon, authenticated;


-- ===== 0006_now_discovery.sql =====
-- =====================================================================
-- Migration 0006: "Now" discovery — open now, live offers, events,
-- new places and the rule-based "وين نروح؟" recommender (no AI).
-- =====================================================================

-- Closing time of a place today (NULL for 24h / closed / unknown).
create or replace function public.todays_close_time(p_business uuid)
returns time language sql stable set search_path = public as $$
  select h.close_time
  from public.businesses b
  left join public.cities c on c.id = b.city_id
  join public.business_hours h on h.business_id = b.id
   and h.day_of_week = extract(dow from (now() at time zone coalesce(c.timezone, 'Asia/Baghdad')))::int
  where b.id = p_business and not h.is_closed and h.open_time <> h.close_time;
$$;

-- ---------------------------------------------------------------------
-- Open now (nearest first when coordinates are given)
-- ---------------------------------------------------------------------
create or replace function public.get_open_now(
  p_city int, p_lat float8 default null, p_lng float8 default null, p_limit int default 12
)
returns table (
  id uuid, slug text, name text, address text, phone text, whatsapp text, district_id int, category_id int,
  rating_avg numeric, rating_count int, is_verified boolean, price_level smallint, distance_km float8,
  closes_at time, last_verified_at timestamptz
)
language sql stable set search_path = public as $$
  select b.id, b.slug, b.name, b.address, b.phone, b.whatsapp, b.district_id, b.category_id,
         b.rating_avg, b.rating_count, b.is_verified, b.price_level,
         case when p_lat is not null and p_lng is not null and b.lat is not null then public.distance_km(p_lat, p_lng, b.lat, b.lng) end,
         public.todays_close_time(b.id), b.last_verified_at
  from public.businesses b
  where b.status = 'active' and b.city_id = p_city and public.is_open_now(b.id) is true
  order by
    case when p_lat is not null and p_lng is not null then public.distance_km(p_lat, p_lng, b.lat, b.lng) end asc nulls last,
    (b.is_featured and (b.featured_until is null or b.featured_until > now())) desc, b.rating_avg desc, b.name
  limit least(greatest(p_limit, 1), 50);
$$;

-- ---------------------------------------------------------------------
-- Live offers (ending soonest first)
-- ---------------------------------------------------------------------
create or replace function public.get_offers_live(p_city int, p_limit int default 20, p_business uuid default null)
returns table (
  id uuid, title text, details text, image_url text, starts_at timestamptz, ends_at timestamptz,
  business_id uuid, business_slug text, business_name text, logo_url text, phone text, district_id int
)
language sql stable set search_path = public as $$
  select o.id, o.title, o.details, o.image_url, o.starts_at, o.ends_at,
         b.id, b.slug, b.name, b.logo_url, b.phone, b.district_id
  from public.offers o
  join public.businesses b on b.id = o.business_id and b.status = 'active'
  where o.city_id = p_city and o.status = 'published' and o.starts_at <= now() and o.ends_at > now()
    and (p_business is null or o.business_id = p_business)
  order by o.ends_at
  limit least(greatest(p_limit, 1), 50);
$$;

-- ---------------------------------------------------------------------
-- Events happening within the next p_days (ongoing ones included)
-- ---------------------------------------------------------------------
create or replace function public.get_events_upcoming(p_city int, p_days int default 14, p_limit int default 20)
returns table (
  id uuid, title text, details text, category text, starts_at timestamptz, ends_at timestamptz,
  venue_name text, venue_slug text, lat float8, lng float8, image_url text
)
language sql stable set search_path = public as $$
  select e.id, e.title, e.details, e.category, e.starts_at, e.ends_at,
         coalesce(e.venue_name, b.name), b.slug, coalesce(e.lat, b.lat), coalesce(e.lng, b.lng), e.image_url
  from public.events e
  left join public.businesses b on b.id = e.venue_business_id
  where e.city_id = p_city and e.status = 'published'
    and coalesce(e.ends_at, e.starts_at + interval '3 hours') >= now()
    and e.starts_at <= now() + make_interval(days => greatest(p_days, 1))
  order by e.starts_at
  limit least(greatest(p_limit, 1), 50);
$$;

-- ---------------------------------------------------------------------
-- New places
-- ---------------------------------------------------------------------
create or replace function public.get_new_places(p_city int, p_days int default 45, p_limit int default 10)
returns table (
  id uuid, slug text, name text, address text, phone text, whatsapp text, district_id int, category_id int,
  rating_avg numeric, rating_count int, is_verified boolean, created_at timestamptz
)
language sql stable set search_path = public as $$
  select b.id, b.slug, b.name, b.address, b.phone, b.whatsapp, b.district_id, b.category_id,
         b.rating_avg, b.rating_count, b.is_verified, b.created_at
  from public.businesses b
  where b.status = 'active' and b.city_id = p_city and b.created_at > now() - make_interval(days => greatest(p_days, 1))
  order by b.created_at desc
  limit least(greatest(p_limit, 1), 50);
$$;

-- ---------------------------------------------------------------------
-- "وين نروح؟" — deterministic matching: open now × audience × budget × distance.
--   p_random = true  -> "فاجئني": one random place that passes the same filters.
-- ---------------------------------------------------------------------
create or replace function public.recommend_places(
  p_city int, p_audience text default null, p_budget int default null, p_max_km float8 default null,
  p_lat float8 default null, p_lng float8 default null, p_random boolean default false,
  p_exclude uuid[] default '{}', p_limit int default 6
)
returns table (
  id uuid, slug text, name text, address text, phone text, whatsapp text, district_id int,
  rating_avg numeric, rating_count int, price_level smallint, distance_km float8, closes_at time,
  audience text, budget_band smallint, amenities text[], last_verified_at timestamptz
)
language sql stable set search_path = public as $$
  with origin as (
    select coalesce(p_lat, c.center_lat) as lat, coalesce(p_lng, c.center_lng) as lng from public.cities c where c.id = p_city
  ),
  cand as (
    select b.*, s.audience as s_aud, s.budget_band as s_band,
           public.distance_km(o.lat, o.lng, b.lat, b.lng) as dist,
           coalesce((select array_agg(a.amenity_key order by a.amenity_key) from public.business_amenities a where a.business_id = b.id), '{}') as ams
    from public.businesses b
    cross join origin o
    left join public.suitability s on s.business_id = b.id and s.audience = p_audience
    where b.status = 'active' and b.city_id = p_city and b.lat is not null
      and not (b.id = any(coalesce(p_exclude, '{}')))
      and public.is_open_now(b.id) is true
      and exists (select 1 from public.categories c left join public.categories par on par.id = c.parent_id
                  where c.id = b.category_id and coalesce(par.slug, c.slug) in ('food', 'malls'))
      and (p_audience is null or s.audience is not null)
      and (p_budget is null or coalesce(s.budget_band, b.price_level, 2) <= p_budget)
      and (p_max_km is null or public.distance_km(o.lat, o.lng, b.lat, b.lng) <= p_max_km)
  )
  select cand.id, cand.slug, cand.name, cand.address, cand.phone, cand.whatsapp, cand.district_id,
         cand.rating_avg, cand.rating_count, cand.price_level, cand.dist, public.todays_close_time(cand.id),
         cand.s_aud, cand.s_band, cand.ams, cand.last_verified_at
  from cand
  order by
    case when p_random then random() end,
    (coalesce(cand.rating_avg, 0) * 2 - cand.dist * 0.8
       + case when cand.is_featured then 1 else 0 end
       + case when p_audience in ('family', 'kids') and ('kids' = any(cand.ams) or 'family' = any(cand.ams)) then 2 else 0 end
       + case when p_audience = 'solo' and ('quiet' = any(cand.ams) or 'wifi' = any(cand.ams)) then 2 else 0 end) desc,
    cand.name
  limit case when p_random then 1 else least(greatest(p_limit, 1), 20) end;
$$;

grant execute on function public.todays_close_time(uuid) to anon, authenticated;
grant execute on function public.get_open_now(int, float8, float8, int) to anon, authenticated;
grant execute on function public.get_offers_live(int, int, uuid) to anon, authenticated;
grant execute on function public.get_events_upcoming(int, int, int) to anon, authenticated;
grant execute on function public.get_new_places(int, int, int) to anon, authenticated;
grant execute on function public.recommend_places(int, text, int, float8, float8, float8, boolean, uuid[], int) to anon, authenticated;


-- ===== 0007_moderation_dashboard.sql =====
-- =====================================================================
-- Migration 0007: moderation, staff tools, owner analytics
-- =====================================================================

create or replace function public.make_slug(p_name text)
returns text language plpgsql volatile set search_path = public as $$
declare base text; candidate text; n int := 0;
begin
  base := trim(both '-' from regexp_replace(lower(coalesce(p_name, '')), '[^a-z0-9]+', '-', 'g'));
  if base = '' or base is null then base := 'place-' || substr(md5(random()::text), 1, 8); end if;
  candidate := base;
  while exists (select 1 from public.businesses where slug = candidate) loop
    n := n + 1; candidate := base || '-' || substr(md5(random()::text), 1, 4);
    exit when n > 20;
  end loop;
  return candidate;
end $$;

create or replace function public.audit(p_action text, p_entity text, p_id text, p_detail jsonb default '{}')
returns void language sql security definer set search_path = public as $$
  insert into public.audit_log (actor_id, action, entity, entity_id, detail) values (auth.uid(), p_action, p_entity, p_id, coalesce(p_detail, '{}'));
$$;
revoke execute on function public.audit(text, text, text, jsonb) from public, anon, authenticated;

-- notify helper (system notifications with a machine-readable event)
create or replace function public._notify_system(p_user uuid, p_event text, p_business uuid default null, p_excerpt text default null)
returns void language sql security definer set search_path = public as $$
  insert into public.notifications (user_id, type, actor_id, business_id, data)
  values (p_user, 'system', auth.uid(), p_business, jsonb_build_object('event', p_event, 'excerpt', p_excerpt));
$$;
revoke execute on function public._notify_system(uuid, text, uuid, text) from public, anon, authenticated;

-- ---------------------------------------------------------------------
-- Submissions (new place / edit)
-- ---------------------------------------------------------------------
create or replace function public.approve_submission(p_id uuid)
returns uuid language plpgsql security definer set search_path = public as $$
declare s public.submissions; bid uuid; pl jsonb; owner_uid uuid;
begin
  if not public.is_staff() then raise exception 'not_allowed'; end if;
  select * into s from public.submissions where id = p_id and status = 'pending' for update;
  if not found then raise exception 'not_found'; end if;
  pl := s.payload;
  if s.type = 'new_place' then
    owner_uid := case when coalesce((pl->>'is_owner')::boolean, false) then s.user_id end;
    insert into public.businesses (slug, name, description, phone, whatsapp, address, category_id, district_id, lat, lng, status, owner_id, city_id)
    values (public.make_slug(pl->>'name'), pl->>'name', nullif(pl->>'description', ''), nullif(pl->>'phone', ''), nullif(pl->>'phone', ''),
            nullif(pl->>'address', ''), (pl->>'category_id')::int, nullif(pl->>'district_id', '')::int,
            nullif(pl->>'lat', '')::float8, nullif(pl->>'lng', '')::float8, 'active', owner_uid, s.city_id)
    returning id into bid;
    if owner_uid is not null then update public.profiles set role = 'owner' where id = owner_uid and role = 'user'; end if;
  else
    bid := s.business_id;
    update public.businesses set
      name = coalesce(nullif(pl->>'name', ''), name), description = coalesce(nullif(pl->>'description', ''), description),
      phone = coalesce(nullif(pl->>'phone', ''), phone), address = coalesce(nullif(pl->>'address', ''), address),
      lat = coalesce(nullif(pl->>'lat', '')::float8, lat), lng = coalesce(nullif(pl->>'lng', '')::float8, lng)
    where id = bid;
  end if;
  update public.submissions set status = 'approved', reviewed_by = auth.uid(), reviewed_at = now() where id = p_id;
  perform public._notify_system(s.user_id, 'submission_approved', bid, pl->>'name');
  perform public.audit('approve_submission', 'submission', p_id::text, jsonb_build_object('business', bid));
  return bid;
end $$;

create or replace function public.reject_submission(p_id uuid, p_note text default null)
returns void language plpgsql security definer set search_path = public as $$
declare s public.submissions;
begin
  if not public.is_staff() then raise exception 'not_allowed'; end if;
  update public.submissions set status = 'rejected', reviewed_by = auth.uid(), reviewed_at = now(), review_note = left(p_note, 300)
   where id = p_id and status = 'pending' returning * into s;
  if not found then raise exception 'not_found'; end if;
  perform public._notify_system(s.user_id, 'submission_rejected', null, s.payload->>'name');
  perform public.audit('reject_submission', 'submission', p_id::text);
end $$;

-- Claims: wrap review_claim with a notification
create or replace function public.review_claim(p_claim uuid, p_approve boolean)
returns void language plpgsql security definer set search_path = public as $$
declare c public.claims;
begin
  if not public.is_staff() then raise exception 'not_allowed'; end if;
  update public.claims set status = case when p_approve then 'approved' else 'rejected' end, reviewed_by = auth.uid()
   where id = p_claim and status = 'pending' returning * into c;
  if not found then raise exception 'not_found'; end if;
  if p_approve then
    update public.businesses set owner_id = c.user_id where id = c.business_id;
    update public.profiles set role = 'owner' where id = c.user_id and role = 'user';
  end if;
  perform public._notify_system(c.user_id, case when p_approve then 'claim_approved' else 'claim_rejected' end, c.business_id, null);
  perform public.audit('review_claim', 'claim', p_claim::text, jsonb_build_object('approved', p_approve));
end $$;

-- ---------------------------------------------------------------------
-- Reports / content moderation
-- ---------------------------------------------------------------------
create or replace function public.moderate_report(p_report uuid, p_action text)   -- dismiss | resolve | hide
returns void language plpgsql security definer set search_path = public as $$
declare r public.reports;
begin
  if not public.is_staff() then raise exception 'not_allowed'; end if;
  if p_action not in ('dismiss', 'resolve', 'hide') then raise exception 'bad_action'; end if;
  select * into r from public.reports where id = p_report;
  if not found then raise exception 'not_found'; end if;
  if p_action = 'hide' then
    case r.target_type
      when 'post'    then update public.posts    set is_hidden = true where id = r.target_id;
      when 'comment' then update public.comments set is_hidden = true where id = r.target_id;
      when 'review'  then update public.reviews  set is_hidden = true where id = r.target_id;
      when 'listing' then update public.listings set status = 'hidden' where id = r.target_id;
      when 'business' then update public.businesses set status = 'suspended' where id = r.target_id;
      else null;
    end case;
  end if;
  update public.reports set status = case p_action when 'dismiss' then 'dismissed'::report_status else 'resolved'::report_status end,
                            handled_by = auth.uid() where id = p_report;
  perform public.audit('moderate_report', 'report', p_report::text, jsonb_build_object('action', p_action, 'target', r.target_type || ':' || r.target_id));
end $$;

create or replace function public.moderate_event(p_event uuid, p_status text)   -- published | hidden
returns void language plpgsql security definer set search_path = public as $$
declare e public.events;
begin
  if not public.is_staff() then raise exception 'not_allowed'; end if;
  if p_status not in ('published', 'hidden') then raise exception 'bad_status'; end if;
  update public.events set status = p_status where id = p_event returning * into e;
  if not found then raise exception 'not_found'; end if;
  if e.created_by is not null then perform public._notify_system(e.created_by, case when p_status = 'published' then 'event_published' else 'event_hidden' end, null, e.title); end if;
  perform public.audit('moderate_event', 'event', p_event::text, jsonb_build_object('status', p_status));
end $$;

-- ---------------------------------------------------------------------
-- Business / user administration
-- ---------------------------------------------------------------------
create or replace function public.set_business_state(
  p_business uuid, p_status text default null, p_verified boolean default null, p_featured_days int default null
) returns void language plpgsql security definer set search_path = public as $$
begin
  if not public.is_staff() then raise exception 'not_allowed'; end if;
  if p_status is not null and p_status not in ('pending', 'active', 'suspended') then raise exception 'bad_status'; end if;
  update public.businesses set
    status = coalesce(p_status::business_status, status),
    is_verified = coalesce(p_verified, is_verified),
    last_verified_at = case when p_verified is true then now() else last_verified_at end,
    verified_by = case when p_verified is true then auth.uid() else verified_by end,
    is_featured = case when p_featured_days is null then is_featured else p_featured_days > 0 end,
    featured_until = case when p_featured_days is null then featured_until when p_featured_days > 0 then now() + make_interval(days => p_featured_days) else null end
  where id = p_business;
  if not found then raise exception 'not_found'; end if;
  perform public.audit('set_business_state', 'business', p_business::text,
    jsonb_build_object('status', p_status, 'verified', p_verified, 'featured_days', p_featured_days));
end $$;

create or replace function public.admin_set_user(p_user uuid, p_role text default null, p_banned boolean default null)
returns void language plpgsql security definer set search_path = public as $$
declare target public.profiles;
begin
  if not public.is_staff() then raise exception 'not_allowed'; end if;
  select * into target from public.profiles where id = p_user;
  if not found then raise exception 'not_found'; end if;
  if p_user = auth.uid() then raise exception 'cannot_modify_self'; end if;
  if p_role is not null then
    if not public.is_admin() then raise exception 'admin_only'; end if;
    if p_role not in ('user', 'owner', 'moderator', 'admin') then raise exception 'bad_role'; end if;
  end if;
  if p_banned is not null and target.role = 'admin' and not public.is_admin() then raise exception 'not_allowed'; end if;
  update public.profiles set role = coalesce(p_role::user_role, role), is_banned = coalesce(p_banned, is_banned) where id = p_user;
  perform public.audit('admin_set_user', 'user', p_user::text, jsonb_build_object('role', p_role, 'banned', p_banned));
end $$;

-- Fast data entry for the field team (verified on the spot, hours preset for every day).
create or replace function public.staff_add_business(p jsonb)
returns uuid language plpgsql security definer set search_path = public as $$
declare bid uuid; o time; c time;
begin
  if not public.is_staff() then raise exception 'not_allowed'; end if;
  insert into public.businesses (slug, name, description, phone, whatsapp, address, category_id, district_id, lat, lng, status,
                                 is_verified, last_verified_at, verified_by, price_level)
  values (public.make_slug(p->>'name'), p->>'name', nullif(p->>'description', ''), nullif(p->>'phone', ''), coalesce(nullif(p->>'whatsapp', ''), nullif(p->>'phone', '')),
          nullif(p->>'address', ''), (p->>'category_id')::int, nullif(p->>'district_id', '')::int,
          nullif(p->>'lat', '')::float8, nullif(p->>'lng', '')::float8, 'active', true, now(), auth.uid(), nullif(p->>'price_level', '')::smallint)
  returning id into bid;
  if nullif(p->>'open', '') is not null and nullif(p->>'close', '') is not null then
    o := (p->>'open')::time; c := (p->>'close')::time;
    insert into public.business_hours (business_id, day_of_week, open_time, close_time) select bid, d, o, c from generate_series(0, 6) d;
  end if;
  perform public.audit('staff_add_business', 'business', bid::text);
  return bid;
end $$;

-- ---------------------------------------------------------------------
-- Owner analytics & admin overview
-- ---------------------------------------------------------------------
create or replace function public.business_stats(p_business uuid, p_days int default 30)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare d int := least(greatest(p_days, 1), 180); res jsonb;
begin
  if not (public.owns_business(p_business) or public.is_staff()) then raise exception 'not_allowed'; end if;
  select jsonb_build_object(
    'days', d,
    'totals', coalesce((select jsonb_object_agg(event, c) from (
        select event, count(*) c from public.analytics_events
        where target_type = 'business' and target_id = p_business and created_at > now() - make_interval(days => d) group by event) t), '{}'::jsonb),
    'daily', (select jsonb_agg(jsonb_build_object('day', g.day, 'views', coalesce(x.views, 0), 'contacts', coalesce(x.contacts, 0), 'directions', coalesce(x.dirs, 0)) order by g.day)
              from (select (((now() at time zone 'Asia/Baghdad')::date) - i) as day from generate_series(d - 1, 0, -1) i) g
              left join (select (created_at at time zone 'Asia/Baghdad')::date as day,
                                count(*) filter (where event = 'view') views,
                                count(*) filter (where event in ('call', 'whatsapp')) contacts,
                                count(*) filter (where event = 'directions') dirs
                         from public.analytics_events
                         where target_type = 'business' and target_id = p_business and created_at > now() - make_interval(days => d + 1) group by 1) x on x.day = g.day),
    'followers', (select followers_count from public.businesses where id = p_business),
    'rating_avg', (select rating_avg from public.businesses where id = p_business),
    'rating_count', (select rating_count from public.businesses where id = p_business)
  ) into res;
  return res;
end $$;
grant execute on function public.business_stats(uuid, int) to authenticated;

create or replace function public.admin_overview()
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  if not public.is_staff() then raise exception 'not_allowed'; end if;
  return jsonb_build_object(
    'pending_submissions', (select count(*) from public.submissions where status = 'pending'),
    'pending_claims',      (select count(*) from public.claims where status = 'pending'),
    'open_reports',        (select count(*) from public.reports where status = 'open'),
    'pending_events',      (select count(*) from public.events where status = 'pending'),
    'pending_businesses',  (select count(*) from public.businesses where status = 'pending'),
    'businesses',          (select count(*) from public.businesses where status = 'active'),
    'unverified',          (select count(*) from public.businesses where status = 'active' and last_verified_at is null),
    'stale',               (select count(*) from public.businesses where status = 'active' and last_verified_at < now() - interval '60 days'),
    'users',               (select count(*) from public.profiles),
    'weekly_active',       (select count(distinct user_id) from public.analytics_events where user_id is not null and created_at > now() - interval '7 days'),
    'events_7d',           (select count(*) from public.analytics_events where created_at > now() - interval '7 days'),
    'contacts_7d',         (select count(*) from public.analytics_events where event in ('call', 'whatsapp', 'directions') and created_at > now() - interval '7 days')
  );
end $$;

