-- ===== 0008_saved_collections_privacy.sql =====
-- =====================================================================
-- Migration 0008: saved items (places/offers/events/listings), curated
-- collections, and account deletion (privacy).
-- =====================================================================

-- ---------------------------------------------------------------------
-- Favorites: extend to offers and events
-- ---------------------------------------------------------------------
alter table public.favorites
  add column offer_id uuid references public.offers(id) on delete cascade,
  add column event_id uuid references public.events(id) on delete cascade;

do $$
declare c record;
begin
  for c in select conname from pg_constraint where conrelid = 'public.favorites'::regclass and contype = 'c' loop
    execute format('alter table public.favorites drop constraint %I', c.conname);
  end loop;
end $$;
alter table public.favorites add constraint favorites_one_target check (num_nonnulls(business_id, listing_id, offer_id, event_id) = 1);
create unique index favorites_offer_uq on public.favorites(user_id, offer_id) where offer_id is not null;
create unique index favorites_event_uq on public.favorites(user_id, event_id) where event_id is not null;

-- Toggle a save; returns the new state. Records a 'save' analytics event for places/offers/events.
create or replace function public.toggle_save(p_type text, p_id uuid)
returns boolean language plpgsql set search_path = public as $$
declare col text; existed boolean; uid uuid := auth.uid();
begin
  if uid is null then raise exception 'auth'; end if;
  if p_type not in ('business', 'listing', 'offer', 'event') then raise exception 'bad_type'; end if;
  col := p_type || '_id';
  execute format('select exists (select 1 from public.favorites where user_id = $1 and %I = $2)', col) into existed using uid, p_id;
  if existed then
    execute format('delete from public.favorites where user_id = $1 and %I = $2', col) using uid, p_id;
    return false;
  end if;
  execute format('insert into public.favorites (user_id, %I) values ($1, $2)', col) using uid, p_id;
  if p_type in ('business', 'offer', 'event') then perform public.track_event('save', case p_type when 'business' then 'business' else p_type end, p_id); end if;
  return true;
end $$;
grant execute on function public.toggle_save(text, uuid) to authenticated;

-- Everything the caller saved, in one round trip.
create or replace function public.get_saved()
returns jsonb language sql stable set search_path = public as $$
  select jsonb_build_object(
    'places', coalesce((select jsonb_agg(x order by x->>'saved_at' desc) from (
        select jsonb_build_object('id', b.id, 'slug', b.slug, 'name', b.name, 'address', b.address, 'phone', b.phone, 'district_id', b.district_id,
               'rating_avg', b.rating_avg, 'rating_count', b.rating_count, 'is_open', public.is_open_now(b.id), 'closes_at', public.todays_close_time(b.id),
               'saved_at', f.created_at) x
        from public.favorites f join public.businesses b on b.id = f.business_id and b.status = 'active' where f.user_id = auth.uid()) s), '[]'),
    'offers', coalesce((select jsonb_agg(x order by x->>'ends_at') from (
        select jsonb_build_object('id', o.id, 'title', o.title, 'details', o.details, 'ends_at', o.ends_at, 'ended', o.ends_at <= now(),
               'business_slug', b.slug, 'business_name', b.name) x
        from public.favorites f join public.offers o on o.id = f.offer_id join public.businesses b on b.id = o.business_id
        where f.user_id = auth.uid() and o.status = 'published') s), '[]'),
    'events', coalesce((select jsonb_agg(x order by x->>'starts_at') from (
        select jsonb_build_object('id', e.id, 'title', e.title, 'details', e.details, 'starts_at', e.starts_at, 'ends_at', e.ends_at,
               'category', e.category, 'venue_name', coalesce(e.venue_name, b.name), 'venue_slug', b.slug, 'past', coalesce(e.ends_at, e.starts_at + interval '3 hours') < now()) x
        from public.favorites f join public.events e on e.id = f.event_id and e.status = 'published' left join public.businesses b on b.id = e.venue_business_id
        where f.user_id = auth.uid()) s), '[]'),
    'listings', coalesce((select jsonb_agg(x order by x->>'saved_at' desc) from (
        select jsonb_build_object('id', l.id, 'kind', l.kind, 'title', l.title, 'price', l.price, 'currency', l.currency, 'details', l.details,
               'district_id', l.district_id, 'status', l.status, 'created_at', l.created_at, 'saved_at', f.created_at,
               'image', (select i.url from public.listing_images i where i.listing_id = l.id order by i.sort_order limit 1)) x
        from public.favorites f join public.listings l on l.id = f.listing_id and l.status <> 'hidden' where f.user_id = auth.uid()) s), '[]')
  );
$$;
grant execute on function public.get_saved() to authenticated;

-- Ids saved by the caller, per kind (to render filled hearts without N queries).
create or replace function public.saved_ids()
returns jsonb language sql stable set search_path = public as $$
  select jsonb_build_object(
    'business', coalesce((select jsonb_agg(business_id) from public.favorites where user_id = auth.uid() and business_id is not null), '[]'),
    'offer',    coalesce((select jsonb_agg(offer_id)    from public.favorites where user_id = auth.uid() and offer_id is not null), '[]'),
    'event',    coalesce((select jsonb_agg(event_id)    from public.favorites where user_id = auth.uid() and event_id is not null), '[]'),
    'listing',  coalesce((select jsonb_agg(listing_id)  from public.favorites where user_id = auth.uid() and listing_id is not null), '[]'));
$$;
grant execute on function public.saved_ids() to authenticated;

-- ---------------------------------------------------------------------
-- Curated collections ("أفضل 5 أماكن فطور")
-- ---------------------------------------------------------------------
create table public.collections (
  id          uuid primary key default gen_random_uuid(),
  city_id     int not null default 1 references public.cities(id),
  slug        text not null unique check (slug ~ '^[a-z0-9-]{3,60}$'),
  title       text not null check (char_length(title) between 3 and 120),
  description text check (char_length(description) <= 500),
  status      text not null default 'draft' check (status in ('draft', 'published')),
  sort_order  int not null default 0,
  created_at  timestamptz not null default now()
);
create table public.collection_items (
  collection_id uuid not null references public.collections(id) on delete cascade,
  business_id   uuid not null references public.businesses(id) on delete cascade,
  position      int not null default 0,
  note          text check (char_length(note) <= 200),
  primary key (collection_id, business_id)
);
create index collection_items_idx on public.collection_items(collection_id, position);
alter table public.collections      enable row level security;
alter table public.collection_items enable row level security;
create policy col_read  on public.collections for select using (status = 'published' or public.is_staff());
create policy col_write on public.collections for all using (public.is_staff()) with check (public.is_staff());
create policy ci_read   on public.collection_items for select
  using (exists (select 1 from public.collections c where c.id = collection_id and (c.status = 'published' or public.is_staff())));
create policy ci_write  on public.collection_items for all using (public.is_staff()) with check (public.is_staff());

create or replace function public.get_collection(p_slug text)
returns jsonb language sql stable set search_path = public as $$
  select jsonb_build_object(
    'id', c.id, 'slug', c.slug, 'title', c.title, 'description', c.description, 'status', c.status,
    'items', coalesce((select jsonb_agg(jsonb_build_object(
        'id', b.id, 'slug', b.slug, 'name', b.name, 'address', b.address, 'phone', b.phone, 'whatsapp', b.whatsapp, 'district_id', b.district_id,
        'rating_avg', b.rating_avg, 'rating_count', b.rating_count, 'is_verified', b.is_verified, 'price_level', b.price_level,
        'is_open', public.is_open_now(b.id), 'closes_at', public.todays_close_time(b.id), 'note', i.note, 'logo_url', b.logo_url) order by i.position, b.name)
      from public.collection_items i join public.businesses b on b.id = i.business_id and b.status = 'active' where i.collection_id = c.id), '[]'))
  from public.collections c where c.slug = p_slug and (c.status = 'published' or public.is_staff());
$$;
grant execute on function public.get_collection(text) to anon, authenticated;

create or replace function public.list_collections(p_city int, p_limit int default 20)
returns table (id uuid, slug text, title text, description text, item_count bigint, preview text[])
language sql stable set search_path = public as $$
  select c.id, c.slug, c.title, c.description,
         (select count(*) from public.collection_items i join public.businesses b on b.id = i.business_id and b.status = 'active' where i.collection_id = c.id),
         (select array_agg(b.name order by i.position) from (select * from public.collection_items where collection_id = c.id order by position limit 3) i join public.businesses b on b.id = i.business_id)
  from public.collections c
  where c.city_id = p_city and c.status = 'published'
  order by c.sort_order, c.created_at desc
  limit least(greatest(p_limit, 1), 50);
$$;
grant execute on function public.list_collections(int, int) to anon, authenticated;

-- ---------------------------------------------------------------------
-- Privacy: delete my account (profile + content cascade; businesses stay, orphaned)
-- ---------------------------------------------------------------------
create or replace function public.delete_my_account()
returns void language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid();
begin
  if uid is null then raise exception 'auth'; end if;
  if (select role from public.profiles where id = uid) = 'admin'
     and (select count(*) from public.profiles where role = 'admin') = 1 then
    raise exception 'last_admin';
  end if;
  insert into public.audit_log (actor_id, action, entity, entity_id) values (uid, 'delete_account', 'user', uid::text);
  delete from auth.users where id = uid;   -- profiles/posts/reviews/... cascade; businesses.owner_id -> null
end $$;
grant execute on function public.delete_my_account() to authenticated;


-- ===== 0009_monetization.sql =====
-- =====================================================================
-- Migration 0009: plans, subscriptions (manual activation), plan limits,
-- sponsored ads. Payment gateways (ZainCash / FastPay / Qi Card) plug in
-- later by calling activate_subscription() from a webhook.
-- =====================================================================

-- Plans: features become per-locale lists {"ar":[...],"en":[...]}
update public.plans set features = jsonb_build_object('ar', features) where jsonb_typeof(features) = 'array';
update public.plans set features = features || case code
  when 'free'     then '{"en":["Basic business page","Up to 5 photos","1 active offer at a time"]}'::jsonb
  when 'pro'      then '{"en":["Verified-first review","Unlimited photos","Unlimited offers","Full analytics"]}'::jsonb
  when 'featured' then '{"en":["Everything in Pro","Top of search results","Featured badge","Shown in sponsored slots"]}'::jsonb
  else '{}'::jsonb end;
update public.plans set features = features || '{"ar":["صفحة نشاط أساسية","حتى 5 صور","عرض واحد فعّال"]}'::jsonb where code = 'free';
update public.plans set features = features || '{"ar":["أولوية في المراجعة والتوثيق","صور غير محدودة","عروض غير محدودة","إحصائيات كاملة"]}'::jsonb where code = 'pro';
update public.plans set features = features || '{"ar":["كل مزايا الاحترافية","ظهور أعلى النتائج","شارة «مميز»","ظهور في المساحات الممولة"]}'::jsonb where code = 'featured';

alter table public.subscriptions
  add column note        text check (char_length(note) <= 300),
  add column amount_iqd  int,
  add column activated_by uuid references public.profiles(id) on delete set null;
-- one open request per business at a time
create unique index subscriptions_one_pending on public.subscriptions(business_id) where status = 'pending';

-- Plan code currently in force for a business ('free' when nothing active).
create or replace function public.active_plan(p_business uuid)
returns text language sql stable security definer set search_path = public as $$
  select coalesce((
    select p.code from public.subscriptions s join public.plans p on p.id = s.plan_id
    where s.business_id = p_business and s.status = 'active' and s.starts_at <= now() and (s.ends_at is null or s.ends_at > now())
    order by p.price_iqd desc limit 1), 'free');
$$;
grant execute on function public.active_plan(uuid) to anon, authenticated;

-- Owners request a plan (never activate it themselves).
drop policy if exists sub_insert on public.subscriptions;
create or replace function public.request_subscription(p_business uuid, p_plan text, p_note text default null)
returns uuid language plpgsql security definer set search_path = public as $$
declare pl public.plans; sid uuid;
begin
  if not public.owns_business(p_business) then raise exception 'not_allowed'; end if;
  select * into pl from public.plans where code = p_plan and is_active and price_iqd > 0;
  if not found then raise exception 'bad_plan'; end if;
  insert into public.subscriptions (business_id, plan_id, status, amount_iqd, note)
  values (p_business, pl.id, 'pending', pl.price_iqd, left(p_note, 300)) returning id into sid;
  perform public.audit('request_subscription', 'subscription', sid::text, jsonb_build_object('plan', p_plan));
  return sid;
end $$;
grant execute on function public.request_subscription(uuid, text, text) to authenticated;

create or replace function public.cancel_subscription_request(p_sub uuid)
returns void language plpgsql security definer set search_path = public as $$
begin
  delete from public.subscriptions s where s.id = p_sub and s.status = 'pending' and (public.owns_business(s.business_id) or public.is_admin());
  if not found then raise exception 'not_found'; end if;
end $$;
grant execute on function public.cancel_subscription_request(uuid) to authenticated;

-- Admin confirms payment (cash / transfer) and activates. The featured tier also features the page.
create or replace function public.activate_subscription(p_sub uuid, p_days int default null, p_payment_ref text default null)
returns void language plpgsql security definer set search_path = public as $$
declare s public.subscriptions; pl public.plans; d int; ends timestamptz;
begin
  if not public.is_admin() then raise exception 'not_allowed'; end if;
  select * into s from public.subscriptions where id = p_sub and status = 'pending' for update;
  if not found then raise exception 'not_found'; end if;
  select * into pl from public.plans where id = s.plan_id;
  d := coalesce(p_days, pl.duration_days);
  if d < 1 or d > 3650 then raise exception 'bad_days'; end if;
  ends := now() + make_interval(days => d);
  update public.subscriptions set status = 'expired', ends_at = now() where business_id = s.business_id and status = 'active';
  update public.subscriptions set status = 'active', starts_at = now(), ends_at = ends, payment_ref = left(p_payment_ref, 120), activated_by = auth.uid() where id = p_sub;
  update public.businesses set is_featured = pl.is_featured_tier, featured_until = case when pl.is_featured_tier then ends end where id = s.business_id;
  perform public._notify_system((select owner_id from public.businesses where id = s.business_id), 'subscription_active', s.business_id, pl.name_ar);
  perform public.audit('activate_subscription', 'subscription', p_sub::text, jsonb_build_object('plan', pl.code, 'days', d, 'ref', p_payment_ref));
end $$;
grant execute on function public.activate_subscription(uuid, int, text) to authenticated;

create or replace function public.cancel_subscription(p_sub uuid)
returns void language plpgsql security definer set search_path = public as $$
declare s public.subscriptions;
begin
  if not public.is_admin() then raise exception 'not_allowed'; end if;
  update public.subscriptions set status = 'cancelled', ends_at = now() where id = p_sub and status = 'active' returning * into s;
  if not found then raise exception 'not_found'; end if;
  update public.businesses set is_featured = false, featured_until = null where id = s.business_id;
  perform public.audit('cancel_subscription', 'subscription', p_sub::text);
end $$;
grant execute on function public.cancel_subscription(uuid) to authenticated;

-- Idempotent housekeeping (run from pg_cron / on admin page load).
create or replace function public.sync_subscriptions()
returns int language plpgsql security definer set search_path = public as $$
declare n int;
begin
  update public.subscriptions set status = 'expired' where status = 'active' and ends_at is not null and ends_at <= now();
  get diagnostics n = row_count;
  update public.businesses b set is_featured = false, featured_until = null
   where b.is_featured and b.featured_until is not null and b.featured_until <= now();
  return n;
end $$;
grant execute on function public.sync_subscriptions() to authenticated;

-- Plan limits (free tier): 5 gallery photos, 1 live offer. Staff / service role bypass.
create or replace function public.enforce_plan_limits()
returns trigger language plpgsql set search_path = public as $$
begin
  if current_user not in ('anon', 'authenticated') or public.is_staff() then return new; end if;
  if tg_table_name = 'business_images' then
    if public.active_plan(new.business_id) = 'free' and (select count(*) from public.business_images where business_id = new.business_id) >= 5 then
      raise exception 'plan_limit_images' using errcode = 'P0001';
    end if;
  elsif tg_table_name = 'offers' then
    if public.active_plan(new.business_id) = 'free'
       and (select count(*) from public.offers where business_id = new.business_id and status = 'published' and ends_at > now()) >= 1 then
      raise exception 'plan_limit_offers' using errcode = 'P0001';
    end if;
  end if;
  return new;
end $$;
create trigger trg_plan_limit_images before insert on public.business_images for each row execute function public.enforce_plan_limits();
create trigger trg_plan_limit_offers before insert on public.offers for each row execute function public.enforce_plan_limits();

-- ---------------------------------------------------------------------
-- Sponsored ads
-- ---------------------------------------------------------------------
create or replace function public.get_ads(p_placement text, p_category int default null, p_limit int default 1)
returns table (id uuid, business_id uuid, business_slug text, title text, body text, image_url text, link_url text)
language sql stable set search_path = public as $$
  select a.id, a.business_id, b.slug, a.title, a.body, a.image_url, a.link_url
  from public.ads a left join public.businesses b on b.id = a.business_id
  where a.placement = p_placement and a.is_active and a.starts_at <= now() and a.ends_at > now()
    and (a.business_id is null or b.status = 'active')
    and (a.category_id is null or a.category_id = p_category)
  order by random()
  limit least(greatest(p_limit, 1), 5);
$$;
grant execute on function public.get_ads(text, int, int) to anon, authenticated;

create or replace function public.track_ad(p_id uuid, p_kind text)
returns void language sql security definer set search_path = public as $$
  update public.ads set impressions = impressions + (p_kind = 'impression')::int, clicks = clicks + (p_kind = 'click')::int
  where id = p_id and p_kind in ('impression', 'click') and is_active;
$$;
grant execute on function public.track_ad(uuid, text) to anon, authenticated;

create or replace function public.ad_target(p_id uuid)
returns text language sql stable security definer set search_path = public as $$
  select coalesce(nullif(a.link_url, ''), '/business/' || b.slug) from public.ads a left join public.businesses b on b.id = a.business_id where a.id = p_id and a.is_active;
$$;
grant execute on function public.ad_target(uuid) to anon, authenticated;


-- ===== 0010_bulk_import.sql =====
-- =====================================================================
-- Migration 0010: staff bulk import of places (CSV -> jsonb rows).
-- dry_run = true validates and reports; false inserts the valid, non-duplicate rows.
-- Imported places are published but NOT verified (no "last verified" date).
-- =====================================================================
create or replace function public.import_businesses(p_rows jsonb, p_dry_run boolean default true)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  r jsonb; i int := 0; city record; cat_id int; dist_id int; nm text; ph text; la float8; ln float8; op text; cl text; pl int;
  errs jsonb := '[]'::jsonb; dups jsonb := '[]'::jsonb; ins int := 0; valid int := 0;
  seen text[] := '{}'; key text; existing uuid; ok boolean; bid uuid; code text;
begin
  if not public.is_staff() then raise exception 'not_allowed'; end if;
  if jsonb_typeof(p_rows) <> 'array' then raise exception 'bad_input'; end if;
  if jsonb_array_length(p_rows) > 1000 then raise exception 'too_many_rows'; end if;
  select id, center_lat, center_lng into city from public.cities where slug = 'kirkuk' limit 1;   -- single-city deployment default

  for r in select * from jsonb_array_elements(p_rows) loop
    i := i + 1; ok := true; code := null;
    nm := nullif(trim(r->>'name'), ''); ph := nullif(regexp_replace(coalesce(r->>'phone', ''), '[^0-9+]', '', 'g'), '');
    la := nullif(trim(r->>'lat'), '')::float8; ln := nullif(trim(r->>'lng'), '')::float8;
    op := nullif(trim(r->>'open'), ''); cl := nullif(trim(r->>'close'), ''); pl := nullif(trim(r->>'price_level'), '')::int;

    if nm is null or char_length(nm) < 2 or char_length(nm) > 120 then code := 'name';
    else
      select id into cat_id from public.categories where slug = trim(r->>'category') and is_active;
      if cat_id is null then code := 'category'; end if;
    end if;
    if code is null and nullif(trim(r->>'district'), '') is not null then
      select id into dist_id from public.districts where slug = trim(r->>'district');
      if dist_id is null then code := 'district'; end if;
    else dist_id := null; end if;
    if code is null and ((la is null) <> (ln is null) or la not between -90 and 90 or ln not between -180 and 180) then code := 'coords'; end if;
    if code is null and la is not null and (abs(la - city.center_lat) > 0.8 or abs(ln - city.center_lng) > 0.8) then code := 'far_from_city'; end if;
    if code is null and ((op is null) <> (cl is null) or (op is not null and (op !~ '^\d{2}:\d{2}$' or cl !~ '^\d{2}:\d{2}$'))) then code := 'hours'; end if;
    if code is null and pl is not null and pl not between 1 and 4 then code := 'price'; end if;

    if code is not null then
      errs := errs || jsonb_build_array(jsonb_build_object('row', i, 'code', code, 'name', nm));
      continue;
    end if;

    -- duplicates: against the batch and against existing places (same normalised name and same phone or < 150 m)
    key := public.ar_normalize(nm) || '|' || coalesce(ph, '');
    select b.id into existing from public.businesses b
     where public.ar_normalize(b.name) = public.ar_normalize(nm)
       and ((ph is not null and regexp_replace(coalesce(b.phone, ''), '[^0-9+]', '', 'g') = ph)
            or (la is not null and b.lat is not null and public.distance_km(la, ln, b.lat, b.lng) < 0.15)
            or (ph is null and la is null)) limit 1;
    if existing is not null or key = any(seen) then
      dups := dups || jsonb_build_array(jsonb_build_object('row', i, 'name', nm, 'existing', existing));
      continue;
    end if;
    seen := seen || key; valid := valid + 1;

    if not p_dry_run then
      insert into public.businesses (slug, name, description, phone, whatsapp, address, category_id, district_id, lat, lng, status, price_level, city_id)
      values (public.make_slug(nm), nm, nullif(trim(r->>'description'), ''), ph, ph, nullif(trim(r->>'address'), ''), cat_id, dist_id, la, ln, 'active', pl, city.id)
      returning id into bid;
      if op is not null then
        insert into public.business_hours (business_id, day_of_week, open_time, close_time) select bid, d, op::time, cl::time from generate_series(0, 6) d;
      end if;
      ins := ins + 1;
    end if;
  end loop;

  if not p_dry_run then perform public.audit('import_businesses', 'business', null, jsonb_build_object('inserted', ins, 'errors', jsonb_array_length(errs), 'duplicates', jsonb_array_length(dups))); end if;
  return jsonb_build_object('total', i, 'valid', valid, 'inserted', ins, 'errors', errs, 'duplicates', dups, 'dry_run', p_dry_run);
end $$;
grant execute on function public.import_businesses(jsonb, boolean) to authenticated;


-- ===== 0011_push.sql =====
-- =====================================================================
-- Migration 0011: Web Push. Notifications are produced by DB triggers (0003/0004/0007/0009);
-- a server-side dispatcher (service role) drains them and sends pushes.
--   * per-user preferences (notification_prefs)
--   * "offer ending soon" alerts for offers the user saved
--   * service-only functions: pending_push / mark_pushed / queue_expiring_offer_alerts
-- =====================================================================

alter table public.notifications add column pushed_at timestamptz;
create index notifications_unpushed_idx on public.notifications(created_at) where pushed_at is null;
alter table public.push_subscriptions add column user_agent text;

create table public.notification_prefs (
  user_id      uuid primary key references public.profiles(id) on delete cascade,
  push_social  boolean not null default false,   -- follows, likes, comments (noisy -> off by default)
  push_offers  boolean not null default true,    -- offers/posts from followed businesses, saved offers ending
  push_reviews boolean not null default true,    -- reviews of my business, replies to my reviews
  push_system  boolean not null default true,    -- submission/claim/event/subscription outcomes
  updated_at   timestamptz not null default now()
);
alter table public.notification_prefs enable row level security;
create policy prefs_own on public.notification_prefs for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create trigger trg_prefs_updated before update on public.notification_prefs for each row execute function public.set_updated_at();

-- Alerts for saved offers that end within 24h (once per user+offer).
create or replace function public.queue_expiring_offer_alerts()
returns int language plpgsql security definer set search_path = public as $$
declare n int;
begin
  insert into public.notifications (user_id, type, business_id, data)
  select f.user_id, 'system', o.business_id, jsonb_build_object('event', 'offer_ending', 'excerpt', o.title, 'offer_id', o.id)
  from public.favorites f join public.offers o on o.id = f.offer_id
  where o.status = 'published' and o.ends_at > now() and o.ends_at <= now() + interval '24 hours'
    and not exists (select 1 from public.notifications x where x.user_id = f.user_id and x.data->>'event' = 'offer_ending' and x.data->>'offer_id' = o.id::text);
  get diagnostics n = row_count;
  return n;
end $$;

-- Pushable notifications: unpushed, recent, user has a subscription and the category is enabled.
create or replace function public.pending_push(p_limit int default 200)
returns table (
  id uuid, user_id uuid, type text, data jsonb, post_id uuid, locale text,
  actor_name text, business_name text, business_slug text, subscriptions jsonb
)
language sql stable security definer set search_path = public as $$
  select n.id, n.user_id, n.type, n.data, n.post_id, p.locale,
         a.full_name, b.name, b.slug,
         (select jsonb_agg(jsonb_build_object('endpoint', s.endpoint, 'keys', s.keys)) from public.push_subscriptions s where s.user_id = n.user_id)
  from public.notifications n
  join public.profiles p on p.id = n.user_id and not p.is_banned
  left join public.notification_prefs np on np.user_id = n.user_id
  left join public.profiles a on a.id = n.actor_id
  left join public.businesses b on b.id = n.business_id
  where n.pushed_at is null and n.read_at is null and n.created_at > now() - interval '6 hours'
    and exists (select 1 from public.push_subscriptions s where s.user_id = n.user_id)
    and case n.type
          when 'follow' then coalesce(np.push_social, false) when 'like' then coalesce(np.push_social, false) when 'comment' then coalesce(np.push_social, false)
          when 'offer' then coalesce(np.push_offers, true) when 'post' then coalesce(np.push_offers, true)
          when 'review' then coalesce(np.push_reviews, true) when 'review_reply' then coalesce(np.push_reviews, true)
          else coalesce(np.push_system, true) end
  order by n.created_at
  limit least(greatest(p_limit, 1), 500);
$$;

create or replace function public.mark_pushed(p_ids uuid[])
returns int language plpgsql security definer set search_path = public as $$
declare n int;
begin
  update public.notifications set pushed_at = now() where id = any(p_ids) and pushed_at is null;
  get diagnostics n = row_count;
  return n;
end $$;

-- Service role only (the dispatcher). Clients must never call these.
revoke execute on function public.queue_expiring_offer_alerts() from public, anon, authenticated;
revoke execute on function public.pending_push(int) from public, anon, authenticated;
revoke execute on function public.mark_pushed(uuid[]) from public, anon, authenticated;
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    grant execute on function public.queue_expiring_offer_alerts() to service_role;
    grant execute on function public.pending_push(int) to service_role;
    grant execute on function public.mark_pushed(uuid[]) to service_role;
  end if;
end $$;


-- ===== 0012_push_health.sql =====
-- Staff-only health snapshot for Web Push (shown at /admin/push).
create or replace function public.admin_push_stats()
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  if not public.is_staff() then raise exception 'not_allowed'; end if;
  return jsonb_build_object(
    'subscribed_users', (select count(distinct user_id) from public.push_subscriptions),
    'devices',          (select count(*) from public.push_subscriptions),
    'backlog',          (select count(*) from public.notifications where pushed_at is null and read_at is null and created_at > now() - interval '6 hours'
                           and exists (select 1 from public.push_subscriptions s where s.user_id = notifications.user_id)),
    'oldest_backlog_min', (select coalesce(round(extract(epoch from now() - min(created_at)) / 60), 0) from public.notifications n
                           where n.pushed_at is null and n.read_at is null and n.created_at > now() - interval '6 hours'
                             and exists (select 1 from public.push_subscriptions s where s.user_id = n.user_id)),
    'pushed_24h',       (select count(*) from public.notifications where pushed_at > now() - interval '24 hours'),
    'last_pushed_at',   (select max(pushed_at) from public.notifications),
    'opted_out_social', (select count(*) from public.notification_prefs where not push_social),
    'prefs_rows',       (select count(*) from public.notification_prefs)
  );
end $$;
revoke execute on function public.admin_push_stats() from public, anon;
grant execute on function public.admin_push_stats() to authenticated;


-- ===== 0013_admin_kpis.sql =====
-- Success KPIs for the admin dashboard (/admin/kpis). Mirrors docs/kpi.sql. Staff only.
create or replace function public.admin_kpis()
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare r jsonb;
begin
  if not public.is_staff() then raise exception 'not_allowed'; end if;
  select jsonb_build_object(
    'weekly', coalesce((
      select jsonb_agg(jsonb_build_object('week', w, 'wau', wau, 'views', views, 'contact', contact) order by w)
      from (select date_trunc('week', created_at at time zone 'Asia/Baghdad')::date w,
                   count(distinct user_id) filter (where user_id is not null) wau,
                   count(*) filter (where event = 'view' and target_type = 'business') views,
                   count(*) filter (where event in ('call','whatsapp','directions') and target_type = 'business') contact
            from public.analytics_events where created_at > now() - interval '8 weeks' group by 1) x), '[]'::jsonb),
    'returning', (
      with w as (select user_id,
                        bool_or(created_at >= date_trunc('week', now())) this_week,
                        bool_or(created_at >= date_trunc('week', now()) - interval '1 week' and created_at < date_trunc('week', now())) last_week
                 from public.analytics_events where user_id is not null and created_at > now() - interval '2 weeks' group by 1)
      select jsonb_build_object('last_week_users', count(*) filter (where last_week), 'returned', count(*) filter (where last_week and this_week)) from w),
    'data', (select jsonb_build_object(
        'published', count(*) filter (where status = 'active'),
        'verified_60d', count(*) filter (where status = 'active' and last_verified_at > now() - interval '60 days'),
        'never_verified', count(*) filter (where status = 'active' and last_verified_at is null)) from public.businesses),
    'money', jsonb_build_object(
        'claims_approved', (select count(*) from public.claims where status = 'approved'),
        'claims_pending',  (select count(*) from public.claims where status = 'pending'),
        'payment_requests',(select count(*) from public.subscriptions where status = 'pending'),
        'paying_now',      (select count(*) from public.subscriptions where status = 'active')),
    'queue', jsonb_build_object(
        'submissions', (select count(*) from public.submissions where status = 'pending'),
        'claims',      (select count(*) from public.claims where status = 'pending'),
        'reports',     (select count(*) from public.reports where status = 'open'),
        'events',      (select count(*) from public.events where status = 'pending'),
        'oldest_open_report', (select min(created_at) from public.reports where status = 'open')),
    'top_places', coalesce((
      select jsonb_agg(jsonb_build_object('slug', slug, 'name', name, 'calls', calls, 'directions', dirs, 'views', views))
      from (select b.slug, b.name,
                   count(*) filter (where e.event in ('call','whatsapp')) calls,
                   count(*) filter (where e.event = 'directions') dirs,
                   count(*) filter (where e.event = 'view') views
            from public.analytics_events e join public.businesses b on b.id = e.target_id
            where e.target_type = 'business' and e.created_at > now() - interval '30 days'
            group by b.slug, b.name order by calls desc, views desc limit 10) t), '[]'::jsonb)
  ) into r;
  return r;
end $$;
revoke execute on function public.admin_kpis() from public, anon;
grant execute on function public.admin_kpis() to authenticated;


-- ===== 0014_reels.sql =====
-- =====================================================================
-- Migration 0014: Reels (short vertical videos)
-- =====================================================================

create table public.reels (
  id          uuid primary key default gen_random_uuid(),
  author_id   uuid not null references public.profiles(id) on delete cascade,
  business_id uuid references public.businesses(id) on delete cascade,
  video_url   text not null,
  caption     text check (char_length(caption) <= 300),
  likes_count int not null default 0,
  views_count int not null default 0,
  is_hidden   boolean not null default false,
  created_at  timestamptz not null default now()
);
create index reels_feed_idx on public.reels(created_at desc) where not is_hidden;
create index reels_author_idx on public.reels(author_id, created_at desc);

create table public.reel_likes (
  reel_id    uuid not null references public.reels(id) on delete cascade,
  user_id    uuid not null references public.profiles(id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (reel_id, user_id)
);

create or replace function public.tg_reel_likes_count()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' then update public.reels set likes_count = likes_count + 1 where id = new.reel_id;
  else update public.reels set likes_count = greatest(likes_count - 1, 0) where id = old.reel_id; end if;
  return null;
end $$;
create trigger reel_likes_count after insert or delete on public.reel_likes
  for each row execute function public.tg_reel_likes_count();

create trigger rl_reels before insert on public.reels
  for each row execute function public.enforce_rate_limit('author_id', '10', '1 day');

-- Views are counted through a definer function so viewers need no write access.
create or replace function public.track_reel_view(p_id uuid)
returns void language sql security definer set search_path = public as $$
  update public.reels set views_count = views_count + 1 where id = p_id and not is_hidden;
$$;
grant execute on function public.track_reel_view(uuid) to anon, authenticated;

-- RLS ------------------------------------------------------------------
alter table public.reels      enable row level security;
alter table public.reel_likes enable row level security;

create policy reels_read on public.reels for select
  using (not is_hidden or author_id = auth.uid() or public.is_staff());
create policy reels_insert on public.reels for insert
  with check (author_id = auth.uid() and not public.is_banned()
              and (business_id is null or public.owns_business(business_id)));
create policy reels_update on public.reels for update
  using (author_id = auth.uid() or public.is_staff())
  with check (author_id = auth.uid() or public.is_staff());
create policy reels_delete on public.reels for delete
  using (author_id = auth.uid() or public.is_staff());

create policy reel_likes_read   on public.reel_likes for select using (true);
create policy reel_likes_insert on public.reel_likes for insert with check (user_id = auth.uid() and not public.is_banned());
create policy reel_likes_delete on public.reel_likes for delete using (user_id = auth.uid());

-- Storage: public bucket for videos (30 MB each), objects under "<auth.uid()>/…"
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types) values
  ('reels', 'reels', true, 31457280, array['video/mp4','video/webm','video/quicktime'])
on conflict (id) do nothing;

create policy "public read reels" on storage.objects for select using (bucket_id = 'reels');
create policy "own folder upload reels" on storage.objects for insert to authenticated
  with check (bucket_id = 'reels' and (storage.foldername(name))[1] = auth.uid()::text);
create policy "own folder delete reels" on storage.objects for delete to authenticated
  using (bucket_id = 'reels' and ((storage.foldername(name))[1] = auth.uid()::text or public.is_staff()));

